//!41f870's bridge-origin sound. The preceding09a60/09870 emitters have their
//!own shared-pool binding; this helper neither replaces nor repeats their RNG.
use crate::Game;
impl Game{
 pub(crate) fn native_bridge_collapse_sound(&mut self,point:[i16;2]){
    self.emit_native_spatial_audio(crate::original_audio::spatial::Chance::Bridge41f870{point});
 }

}
#[cfg(test)]mod tests{
 use super::*;use crate::{json,original_combat::Attack};
 fn field()->Game{let mut g=Game::new(0,1,41870);g.map.original=true;g.map.width=64;g.map.height=64;g.map.tiles=vec![0;4096];g.map.terrain_codes=vec![0;4096];g.map.native_terrain_plane=vec![0;16384];g.map.original_tiles=vec![0;4096];g.map.native_tile_plane=vec![0;16384];g.map.bridge_base=vec![-1;4096];g.map.bridge_hp=vec![1.];g.map.bridge_max_hp=vec![200.];g.units.clear();g.buildings.clear();g.objects.clear();g.crates.clear();g.walls.clear();g.sectors.clear();g.native_world=None;g.native_strategy=None;g.native_group_rosters=Default::default();g.ai_teams.clear();g.native_view=Some(([0,0],[640,480]));g.import_native_world(&json!({"bridges":[{"id":0,"nativeSlot":0,"nativeOrientation":0,"x":640,"y":640,"w":192,"h":96,"hp":1,"maxHp":200}]}));g.native_feedback.sound_enabled=1;g.native_feedback.ui_clock=120;g}
 #[test]fn bridge_death_ignores_the_explosion_gate_and_quiet_flag_then_preserves_collapse(){let mut g=field();g.native_audio.opportunity_gate=1;g.native_world.as_mut().unwrap().quiet_blasts=true;g.spawn("grunt",0,680.,680.,1,None);g.maintain_native_group_rosters();let before=g.original_rng.words;g.damage_native_bridge([320,320],1,0);assert_eq!(g.native_audio.explosion_cycle,1);assert!((g.native_audio.opportunity_gate!=0));assert!(g.native_blast_quiet());assert_eq!(g.events.iter().filter(|e|e["kind"]=="nativeSample").map(|e|e["sampleId"].as_i64().unwrap()).collect::<Vec<_>>(),[1]);assert!(g.units[0].hp<0.);assert_eq!(g.map.bridge_hp[0],0.);let sound=g.events.iter().position(|e|e["kind"]=="nativeSample").unwrap();let destroyed=g.events.iter().position(|e|e["kind"]=="bridgeDestroyed").unwrap();assert!(sound<destroyed);assert_ne!(g.original_rng.words,before,"the existing UNIT-removal leaf remains active");let cycle=g.native_audio.explosion_cycle;g.damage_native_bridge([320,320],255,0);assert_eq!(g.native_audio.explosion_cycle,cycle,"already destroyed bridge cannot emit again");}
 #[test]fn ordinary_blast_prefix_and_bridge_death_emit_two_different_descriptors_in_one_callback(){let mut g=field();g.set_world_code(20*128+20,23);let attack=Attack{target:0,damage:1,aim:0,facing:0,bullet:false};g.spawn_native_blast(308,288,attack,0,None);assert_eq!(g.native_audio.explosion_cycle,2);assert!((g.native_audio.opportunity_gate!=0));assert_eq!(g.events.iter().filter(|e|e["kind"]=="nativeSample").map(|e|e["sampleId"].as_i64().unwrap()).collect::<Vec<_>>(),[1,2]);assert_eq!(g.native_audio.effect_counter,2);}
 #[test]fn visible_disabled_or_throttled_calls_advance_cycle_but_do_not_touch_gate_counter_or_rng(){let mut g=field();let before=g.original_rng.words;g.native_feedback.sound_enabled=0;g.native_audio.opportunity_gate=1;g.native_bridge_collapse_sound([320,320]);assert_eq!(g.native_audio.explosion_cycle,1);assert_eq!(g.native_audio.effect_counter,0);assert!((g.native_audio.opportunity_gate!=0));g.native_feedback.sound_enabled=1;g.native_feedback.ui_clock=0;g.native_bridge_collapse_sound([320,320]);assert_eq!(g.native_audio.explosion_cycle,2);assert_eq!(g.native_audio.effect_counter,0);assert_eq!(g.original_rng.words,before);assert!(g.events.is_empty());g.native_view=Some(([1200,0],[640,480]));g.native_bridge_collapse_sound([320,320]);assert_eq!(g.native_audio.explosion_cycle,2);}
 #[test]fn view_admission_has_no_map_bounds_gate(){let mut g=field();g.native_view=Some(([3000,3000],[640,480]));g.native_bridge_collapse_sound([3100,3100]);assert_eq!(g.native_audio.explosion_cycle,1);assert_eq!(g.native_audio.effect_counter,1);assert!(!(g.native_audio.opportunity_gate!=0));}
 #[test]fn first_half_health_transition_keeps_the_sound_cycle_unchanged(){let mut g=field();g.map.bridge_hp[0]=101.;g.sync_native_world();g.damage_native_bridge([320,320],1,0);assert_eq!(g.native_audio.explosion_cycle,0);assert_eq!(g.native_audio.effect_counter,0);assert!(g.events.iter().any(|e|e["kind"]=="bridgeDamaged"));assert_eq!(g.map.bridge_hp[0],100.);}
}
